    }

    record WormSuccessor(
            String acceptedReportSha256,
            String acceptedBuildContextSha256,
            int acceptedChainNodeCount,
            String currentReportSha256,
            String currentBuildContextSha256,
            int currentChainNodeCount) {
    }
